17	// EmailSender sends a prepared email message with the given SMTP configuration.
18	type EmailSender func(*email.Config, *email.Message)
19	
20	// EmailDispatcher dispatches notification emails for inbox events.
21	type EmailDispatcher struct {
22		profile *profile.Profile
23		store   *store.Store
24		sender  EmailSender
25	}
