283	func (d *EmailDispatcher) baseURL() string {
284		if d.profile == nil || strings.TrimSpace(d.profile.InstanceURL) == "" {
285			return ""
286		}
287		return strings.TrimRight(strings.TrimSpace(d.profile.InstanceURL), "/")
288	}
289	
290	func (d *EmailDispatcher) memoURL(memo *store.Memo) string {
291		baseURL := d.baseURL()
292		if memo == nil || memo.UID == "" || baseURL == "" {
293			return ""
294		}
295		return fmt.Sprintf("%s/memos/%s", baseURL, memo.UID)
296	}
297	
298	func (d *EmailDispatcher) memoCommentURL(relatedMemo *store.Memo, commentMemo *store.Memo) string {
299		baseURL := d.baseURL()
300		if relatedMemo == nil || relatedMemo.UID == "" || commentMemo == nil || commentMemo.UID == "" || baseURL == "" {
301			return ""
302		}
303		return fmt.Sprintf("%s/memos/%s#%s", baseURL, relatedMemo.UID, commentMemo.UID)
304	}
305	
306	func canViewerAccessMemo(viewer *store.User, memo *store.Memo) bool {
307		if memo == nil {
308			return false
309		}
310		if viewer != nil && viewer.Role == store.RoleAdmin {
311			return true
312		}
313		if memo.Visibility == store.Private {
314			return viewer != nil && viewer.ID == memo.CreatorID
315		}
316		if memo.Visibility == store.Protected {
317			return viewer != nil
318		}
319		return true
320	}
